// Package storage persists uploaded files behind a small seam (design D1).
//
// The Store interface lets the KYC document uploads write files without
// depending on a concrete backend: LocalStore implements it on the local
// filesystem, and a cloud object store can be swapped in later behind the
// same interface. Keys are always generated by the application (UUID +
// sanitized extension) and never come from user input.
package storage

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
)

// ErrInvalidKycType is returned when an uploaded document's extension or
// sniffed content is not in the whitelist (jpg/png/pdf), or the two disagree
// (design D2 — 415).
var ErrInvalidKycType = errors.New("unsupported document type: only jpg, png and pdf files are allowed")

// ErrInvalidKey is returned when a storage key is empty, absolute, or escapes
// the storage directory.
var ErrInvalidKey = errors.New("invalid storage key")

// kycExts maps whitelisted upload extensions to the canonical stored
// extension. .jpeg normalizes to .jpg so stored keys never carry a second
// alias; lookup is case-insensitive.
var kycExts = map[string]string{
	".jpg":  "jpg",
	".jpeg": "jpg",
	".png":  "png",
	".pdf":  "pdf",
}

// Store persists opaque files under caller-chosen keys. Implementations must
// treat keys as application-generated identifiers, never as user-controlled
// paths (design D1).
type Store interface {
	// Save writes r to the storage under key and returns the number of bytes
	// written. The caller owns the key: it must be safe for the backend.
	Save(ctx context.Context, key string, r io.Reader) (int64, error)

	// Delete removes the file stored under key. It is used as compensation
	// when a stored file has no matching metadata row (design D2: nothing is
	// stored on a rejection path). Deleting a key that does not exist is a
	// no-op, so callers can invoke it without knowing whether Save landed.
	Delete(ctx context.Context, key string) error
}

// LocalStore stores files on the local filesystem under a base directory
// (KYC_STORAGE_DIR). The directory is created lazily on the first Save.
type LocalStore struct {
	dir string
}

// NewLocalStore creates a LocalStore rooted at dir.
func NewLocalStore(dir string) *LocalStore {
	return &LocalStore{dir: dir}
}

// Save writes r to <dir>/<key> and returns the number of bytes written. The
// key must be a bare file name: empty, absolute, separator-containing and
// ".."-containing keys are rejected before any filesystem operation, so a key
// can never escape the storage directory. Files are created with O_EXCL so an
// existing key is never silently overwritten (keys are fresh UUIDs in
// practice, which makes collisions effectively impossible).
func (s *LocalStore) Save(ctx context.Context, key string, r io.Reader) (int64, error) {
	if err := validateKey(key); err != nil {
		return 0, err
	}

	if err := os.MkdirAll(s.dir, 0o750); err != nil {
		return 0, fmt.Errorf("create storage dir: %w", err)
	}

	full := filepath.Join(s.dir, key)
	f, err := os.OpenFile(full, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o640)
	if err != nil {
		return 0, fmt.Errorf("open stored file: %w", err)
	}

	n, copyErr := io.Copy(f, r)
	closeErr := f.Close()
	if copyErr != nil {
		_ = os.Remove(full)
		return n, fmt.Errorf("write stored file: %w", copyErr)
	}
	if closeErr != nil {
		_ = os.Remove(full)
		return n, fmt.Errorf("close stored file: %w", closeErr)
	}
	return n, nil
}

// validateKey rejects keys that could escape the storage directory. Path
// separators are rejected explicitly (not just via filepath) because
// filepath treats backslash as a separator only on Windows; keys are bare
// file names and must never contain either separator on any platform.
func validateKey(key string) error {
	if key == "" || filepath.IsAbs(key) || filepath.Base(key) != key ||
		strings.ContainsAny(key, `/\`) || strings.Contains(key, "..") {
		return ErrInvalidKey
	}
	return nil
}

// Delete removes <dir>/<key> as compensation for a stored file whose metadata
// row could not be persisted. It is idempotent: a key that does not exist
// yields nil, so the handler can always call it after a failed metadata write
// without distinguishing which failure happened.
func (s *LocalStore) Delete(ctx context.Context, key string) error {
	if err := validateKey(key); err != nil {
		return err
	}
	full := filepath.Join(s.dir, key)
	if err := os.Remove(full); err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return fmt.Errorf("remove stored file: %w", err)
	}
	return nil
}

// ValidateKycDocument validates an uploaded document against the design D2
// whitelist: the extension must be jpg/jpeg/png/pdf AND the sniffed content
// must agree with it. On success it returns the canonical stored extension and
// the canonical content type. The sniff uses http.DetectContentType for
// images and an explicit "%PDF-" magic check for PDFs.
func ValidateKycDocument(filename string, data []byte) (string, string, error) {
	ext := strings.ToLower(filepath.Ext(filename))
	canonical, ok := kycExts[ext]
	if !ok {
		return "", "", ErrInvalidKycType
	}

	ct := sniffContentType(data)
	switch canonical {
	case "jpg":
		if ct != "image/jpeg" {
			return "", "", ErrInvalidKycType
		}
		return "jpg", "image/jpeg", nil
	case "png":
		if ct != "image/png" {
			return "", "", ErrInvalidKycType
		}
		return "png", "image/png", nil
	case "pdf":
		if ct != "application/pdf" {
			return "", "", ErrInvalidKycType
		}
		return "pdf", "application/pdf", nil
	}
	return "", "", ErrInvalidKycType
}

// sniffContentType determines the document's real type from its leading
// bytes: an explicit "%PDF-" magic check plus http.DetectContentType for the
// image types. Anything else reports "" so the whitelist rejects it.
func sniffContentType(data []byte) string {
	if len(data) >= 5 && string(data[:5]) == "%PDF-" {
		return "application/pdf"
	}
	ct := http.DetectContentType(data)
	if ct == "image/jpeg" || ct == "image/png" {
		return ct
	}
	return ""
}
